head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. wframeTreeView.xml 을 브라우저로 실행한다.
    //1. Run wframeTreeView.xml in your browser.
    //Verify 1. Wframe 안에 트리뷰가 바인딩되서 보여진다.
    //1. A tree view is displayed in Wframe.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wframe1_treeview1').childNodes.length != 0", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wframe1_treeview1_label_1').text() == 'aa'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 01-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
